'use strict';
(()=>{
const account=window.RepoAccount,access=document.getElementById('connect-access'),setup=document.getElementById('connect-setup'),status=document.getElementById('copy-status');
function render(){if(!account.ready)return;const signedIn=Boolean(account.user?.githubConnected)&&!account.legal.required;setup.hidden=!signedIn;access.replaceChildren();const text=document.createElement('p');text.textContent=signedIn?'You’re signed in. Set up the connector on the computer where you use your AI assistant.':account.legal.required?'Review the current terms to continue.':account.enabled?'Sign in with GitHub to open the setup guide.':'GitHub sign-in is temporarily unavailable. Please try again later.';access.append(text);if(!signedIn&&(account.enabled||account.legal.required)){const link=document.createElement('a');link.className='button lime';link.href=account.legal.required?'/legal.html':'/api/auth?action=start&return=%2Fconnect.html';link.textContent=account.legal.required?'Review terms':'Sign in with GitHub';access.append(link)}}
window.addEventListener('reposhelf-account',render);render();
document.querySelectorAll('[data-client]').forEach(button=>button.addEventListener('click',()=>{const chosen=button.dataset.client;for(const client of ['codex','claude'])document.getElementById(client+'-setup').hidden=client!==chosen;document.querySelectorAll('[data-client]').forEach(option=>{const active=option.dataset.client===chosen;option.setAttribute('aria-pressed',String(active));option.classList.toggle('lime',active);option.classList.toggle('outline',!active)})}));
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{if(!account.user?.githubConnected||account.legal.required){render();return}try{await navigator.clipboard.writeText(document.getElementById(button.dataset.copy).textContent);status.textContent='Copied. Paste it into your terminal or assistant configuration.'}catch{status.textContent='Copy was unavailable. Select the text above and copy it manually.'}}));
})();
